import{_ as n,o as a,c as p,ae as l}from"./chunks/framework.DICTGE3h.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"note/ai/agent/output/手把手教你写一个skill.md","filePath":"note/ai/agent/output/手把手教你写一个skill.md"}'),e={name:"note/ai/agent/output/手把手教你写一个skill.md"};function i(c,s,t,o,r,d){return a(),p("div",null,[...s[0]||(s[0]=[l(`<p>回想一下平常工作中有哪些重复做的事情，比如每周五下班前需要写一份周报。</p><h2 id="skill-完整结构" tabindex="-1">skill 完整结构 <a class="header-anchor" href="#skill-完整结构" aria-label="Permalink to &quot;skill 完整结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: work-summary-writing</span></span>
<span class="line"><span>description: 当用户提到撰写、润色或生成工作总结、周报、月报、季度总结、年度总结、项目复盘、阶段性汇报时使用。该技能用于帮助用户把零散工作内容整理成结构清晰、重点明确、</span></span>
<span class="line"><span>表达正式自然的总结文本。</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 工作总结写作</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 写作步骤</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 1. 明确总结范围</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先判断总结的时间范围和使用场景，例如：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 周报</span></span>
<span class="line"><span>- 月报</span></span>
<span class="line"><span>- 季度总结</span></span>
<span class="line"><span>- 年度总结</span></span>
<span class="line"><span>- 项目阶段总结</span></span>
<span class="line"><span>- 个人工作复盘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果用户没有说明时间范围，可使用“本阶段”作为默认表述。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 2. 提炼核心工作</span></span>
<span class="line"><span></span></span>
<span class="line"><span>从用户提供的信息中提取主要工作内容。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>优先识别：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 负责了什么任务</span></span>
<span class="line"><span>- 推进了哪些项目</span></span>
<span class="line"><span>- 解决了哪些问题</span></span>
<span class="line"><span>- 参与了哪些协作</span></span>
<span class="line"><span>- 完成了哪些交付</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 3. 整理工作成果</span></span>
<span class="line"><span></span></span>
<span class="line"><span>将工作内容转化为结果表达。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>尽量补充：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 完成情况</span></span>
<span class="line"><span>- 进展状态</span></span>
<span class="line"><span>- 产生的价值</span></span>
<span class="line"><span>- 效率提升</span></span>
<span class="line"><span>- 问题解决效果</span></span>
<span class="line"><span>- 可量化数据</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果用户没有提供数据，不要编造，可使用“提升了工作效率”“推动了项目进展”等稳妥表达。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 4. 分析问题与不足</span></span>
<span class="line"><span></span></span>
<span class="line"><span>客观总结工作中存在的问题。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>可以从以下角度整理：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 进度是否受阻</span></span>
<span class="line"><span>- 沟通是否充分</span></span>
<span class="line"><span>- 流程是否顺畅</span></span>
<span class="line"><span>- 方案是否还有优化空间</span></span>
<span class="line"><span>- 个人能力是否需要提升</span></span>
<span class="line"><span></span></span>
<span class="line"><span>表达要克制，不夸大问题，也不回避问题。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 5. 提炼经验与反思</span></span>
<span class="line"><span></span></span>
<span class="line"><span>总结本阶段获得的经验。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>重点写：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 哪些方法有效</span></span>
<span class="line"><span>- 哪些流程可以复用</span></span>
<span class="line"><span>- 哪些协作方式值得保留</span></span>
<span class="line"><span>- 后续可以如何改进</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 6. 制定下一步计划</span></span>
<span class="line"><span></span></span>
<span class="line"><span>根据前文内容，提出后续计划。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>计划应具体、可执行，例如：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 继续推进某项任务</span></span>
<span class="line"><span>- 优化某个流程</span></span>
<span class="line"><span>- 提升某项能力</span></span>
<span class="line"><span>- 完成某个交付</span></span>
<span class="line"><span>- 加强沟通协作</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 推荐结构</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`text</span></span>
<span class="line"><span>一、总体情况</span></span>
<span class="line"><span>简要说明本阶段的工作重点和整体完成情况。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>二、主要工作</span></span>
<span class="line"><span>分条说明完成的重点事项。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>三、工作成果</span></span>
<span class="line"><span>总结取得的结果、进展或价值。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>四、问题与不足</span></span>
<span class="line"><span>客观说明存在的问题和改进空间。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>五、经验总结</span></span>
<span class="line"><span>提炼本阶段的收获和方法。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>六、下一步计划</span></span>
<span class="line"><span>说明后续重点工作安排。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 注意事项</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 不要虚构关键事实、数据、项目名称或成果。</span></span>
<span class="line"><span>- 用户提供的信息不足时，可以使用通用表达，但应避免写得过满。</span></span>
<span class="line"><span>- 表达要正式、自然、简洁，避免口号式语言。</span></span>
<span class="line"><span>- 多写具体行动和实际结果，少写空泛态度。</span></span>
<span class="line"><span>- 总结个人工作时，突出职责和贡献，但不要过度夸大。</span></span>
<span class="line"><span>- 总结团队工作时，注意使用“我们”“团队”等表述。</span></span>
<span class="line"><span>- 问题与不足要真实可改进，不要写成严重失误。</span></span>
<span class="line"><span>- 下一步计划要和前文问题、成果形成呼应。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 输出要求</span></span>
<span class="line"><span></span></span>
<span class="line"><span>默认输出一篇完整工作总结。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果用户只要求框架，则只输出结构和要点。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果用户提供了原始素材，应优先基于素材改写，不随意扩展事实。</span></span></code></pre></div><p>我们来拆解下：</p><ol><li>name：skill 的名字，简短英文名。</li><li>description: skill 的描述，说明这个 skill 是做什么的，以及触发条件。大模型在识别到对应触发场景后，会按需加载这个 skill 进行使用。</li><li>正文：skill 的具体实现，教AI怎么一步步完成这个任务</li><li>注意事项：边界条件和禁区，这是通过被坑的血泪教训总结而来的。</li><li>输出要求：skill 的输出格式。</li></ol><h2 id="将-skill-保存到正确位置" tabindex="-1">将 Skill 保存到正确位置 <a class="header-anchor" href="#将-skill-保存到正确位置" aria-label="Permalink to &quot;将 Skill 保存到正确位置&quot;">​</a></h2><p>不同的 agent，skill 的存放位置不同，比如 claude code 是 <code>.claude/skills/work-summary-writing/SKILL.md</code>，codex 是 <code>.codex/skills/work-summary-writing/SKILL.md</code>。</p><h2 id="测试触发" tabindex="-1">测试触发 <a class="header-anchor" href="#测试触发" aria-label="Permalink to &quot;测试触发&quot;">​</a></h2><p>将 Skill 保存到正确位置后，用对应的触发提示词比如「帮我写周报」看 Skill 是否会被触发。</p>`,9)])])}const u=n(e,[["render",i]]);export{_ as __pageData,u as default};
